export const getCrmLeadContext = async (id: string,
    params?: GetCrmLeadContextParams, options?: RequestInit): Promise<CrmLeadContext> => {

  return customFetch<CrmLeadContext>(getGetCrmLeadContextUrl(id,params),
  {
    ...options,
    method: 'GET'


  }
);}





